# Read-only PowerShell probe: metadata/AST/in-memory mocks only; no binary launch or file writes.
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$source = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$tokens = $null; $errors = $null
$null = [Management.Automation.Language.Parser]::ParseInput($source, [ref]$tokens, [ref]$errors)
if (@($errors).Count -ne 0) { throw 'Full CI source has parser errors.' }
function Resolve-Application([string]$Name) {
    # -All preserves execution precedence; duplicate PATH entries are legitimate.
    $commands = @(Get-Command -Name $Name -CommandType Application -All -ErrorAction Stop |
        Select-Object -First 1)
    if ($commands.Count -ne 1) { throw "Application not found: $Name" }
    $source = [string]$commands[0].Source
    if ([string]::IsNullOrWhiteSpace($source) -or -not [IO.Path]::IsPathRooted($source)) {
        throw "Application path is not absolute: $Name"
    }
    $path = [IO.Path]::GetFullPath($source)
    # IsPathRooted alone also accepts C:relative and \drive-relative on Windows.
    $sourceRoot = [IO.Path]::GetPathRoot($source).Replace('/', '\')
    $fullRoot = [IO.Path]::GetPathRoot($path).Replace('/', '\')
    if (-not [string]::Equals($sourceRoot, $fullRoot, [StringComparison]::OrdinalIgnoreCase) -or
        -not [IO.File]::Exists($path)) {
        throw "Application path is not an existing absolute file: $Name"
    }
    return $path
}

$cases = [Collections.Generic.List[object]]::new()
foreach ($name in @('cmd.exe', 'powershell.exe')) {
    $native = @(Microsoft.PowerShell.Core\Get-Command -Name $name -CommandType Application -All -ErrorAction Stop)
    $actual = @(Resolve-Application $name)
    if ($actual.Count -ne 1 -or $actual[0] -isnot [string] -or
        -not [string]::Equals($actual[0], [IO.Path]::GetFullPath($native[0].Source), [StringComparison]::OrdinalIgnoreCase)) {
        throw 'Real application metadata did not preserve first PATH match.'
    }
    $cases.Add([ordered]@{name = "real-$name-first-path"; passed = $true; matches = $native.Count})
}
$a = Join-Path $env:SystemRoot 'System32\cmd.exe'
$b = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
if (-not [IO.File]::Exists($a) -or -not [IO.File]::Exists($b)) { throw 'Readonly fixture binaries missing.' }
$missing = Join-Path $env:SystemRoot 'System32\future-classroom-ci-resolution-missing-3f37e083d0684d548916514b106915c7.exe'
if ([IO.File]::Exists($missing)) { throw 'Missing-path fixture unexpectedly exists.' }
$script:MockSources = @()
function Get-Command {
    [CmdletBinding()]
    param([string]$Name, [string]$CommandType, [switch]$All)
    if ($Name -ne 'fixture.exe' -or $CommandType -ne 'Application' -or -not $All) {
        throw 'Unexpected command lookup in readonly test.'
    }
    foreach ($source in $script:MockSources) { [pscustomobject]@{Source = $source} }
}
function Assert-Resolution([string]$Label, [object[]]$Sources, [string]$Expected) {
    $script:MockSources = $Sources
    $actual = @(Resolve-Application 'fixture.exe')
    if ($actual.Count -ne 1 -or $actual[0] -isnot [string] -or
        -not [string]::Equals($actual[0], [IO.Path]::GetFullPath($Expected), [StringComparison]::OrdinalIgnoreCase)) {
        throw "Unexpected resolution: $Label"
    }
    $cases.Add([ordered]@{name = $Label; passed = $true})
}
function Assert-Rejected([string]$Label, [object[]]$Sources) {
    $script:MockSources = $Sources
    $rejected = $false
    try { $null = Resolve-Application 'fixture.exe' } catch { $rejected = $true }
    if (-not $rejected) { throw "Expected fail-closed rejection: $Label" }
    $cases.Add([ordered]@{name = $Label; passed = $true})
}
try {
    Assert-Resolution 'first-path-priority' @($a, $b) $a
    Assert-Resolution 'reversed-path-priority' @($b, $a) $b
    Assert-Resolution 'legitimate-duplicate-paths' @($a, $a, $b) $a
    Assert-Resolution 'later-invalid-path-irrelevant' @($a, $missing) $a
    Assert-Rejected 'empty-match' @()
    Assert-Rejected 'empty-source' @('')
    Assert-Rejected 'relative-source' @('cmd.exe')
    Assert-Rejected 'drive-relative-source' @('C:cmd.exe')
    Assert-Rejected 'rooted-without-drive-source' @('\Windows\System32\cmd.exe')
    Assert-Rejected 'directory-source' @($env:SystemRoot)
    Assert-Rejected 'missing-file-source' @($missing)
    Assert-Rejected 'invalid-first-does-not-fallback' @($missing, $a)
} finally {
    Remove-Item Function:Get-Command
}
[ordered]@{
    status = 'PASS'; scope = 'READONLY_AST_AND_APPLICATION_METADATA_NO_PROCESS_LAUNCH_NO_FILE_WRITES'
    powershell = $PSVersionTable.PSVersion.ToString(); sourceSha256 = '241b3afe56cd31075dc400e6808615f138b5f2b6c844e9c23a87cdeb0976cd81'; parserErrors = @($errors).Count
    caseCount = $cases.Count; cases = $cases.ToArray()
} | ConvertTo-Json -Depth 8 -Compress
